//! Plays the bundled reminder chime on every desktop platform.

use std::io::Cursor;
use std::sync::mpsc::{self, RecvTimeoutError, SyncSender};
use std::time::Duration;

use log::warn;
use rodio::{Decoder, OutputStream, Sink};

/// The chime is generated by `scripts/generate-sound.mjs` and embedded in the
/// binary, so playback does not depend on the operating system sound scheme.
static CHIME: &[u8] = include_bytes!("../assets/notification.wav");

const START_TIMEOUT: Duration = Duration::from_secs(2);

/// Plays the chime and waits until the audio device accepted it. Used by the
/// settings preview, where a real error is better than a silent failure.
pub fn play_notification() -> Result<(), String> {
    start(true)
}

/// Starts the chime without waiting. Used when a session ends so the timer
/// thread never blocks on audio initialization.
pub fn play_notification_in_background() {
    if let Err(error) = start(false) {
        warn!("failed to start reminder sound: {error}");
    }
}

fn start(wait: bool) -> Result<(), String> {
    let (ready, receiver) = mpsc::sync_channel(1);
    std::thread::Builder::new()
        .name("reminder-sound".to_owned())
        .spawn(move || play_blocking(ready))
        .map_err(|error| error.to_string())?;
    if !wait {
        return Ok(());
    }
    match receiver.recv_timeout(START_TIMEOUT) {
        Ok(result) => result,
        Err(RecvTimeoutError::Timeout) => Err("the audio device did not respond".to_owned()),
        Err(RecvTimeoutError::Disconnected) => Err("the audio device is unavailable".to_owned()),
    }
}

fn play_blocking(ready: SyncSender<Result<(), String>>) {
    match open_chime() {
        Ok((stream, sink)) => {
            let _ = ready.send(Ok(()));
            sink.sleep_until_end();
            drop(stream);
        }
        Err(error) => {
            let _ = ready.send(Err(error.clone()));
            warn!("failed to play reminder sound: {error}");
        }
    }
}

fn open_chime() -> Result<(OutputStream, Sink), String> {
    let stream =
        rodio::OutputStreamBuilder::open_default_stream().map_err(|error| error.to_string())?;
    let sink = Sink::connect_new(stream.mixer());
    let source = Decoder::new(Cursor::new(CHIME)).map_err(|error| error.to_string())?;
    sink.append(source);
    Ok((stream, sink))
}

#[cfg(test)]
mod tests {
    use super::*;
    use rodio::Source;

    #[test]
    fn the_bundled_chime_decodes_with_its_full_duration() {
        let decoder = Decoder::new(Cursor::new(CHIME)).expect("chime decodes");
        let duration = decoder.total_duration().expect("chime has a duration");
        assert!(duration >= Duration::from_millis(900));
    }
}
